import{_ as n,o as s,c as a,a as e,e as i}from"./app.547295de.js?v=20260723-v2.9.0-fast-submit-feedback";const _={},h=i(`<div class="sd-guide sd-guide-pager" data-guide-pager><div class="sd-guide-pager__viewport"><div class="sd-guide-pager__pages"><section class="sd-guide-pager__page is-active" data-guide-page="0" id="guide-page-intro" aria-label="新手上路"><div class="sd-guide-intro sd-guide-intro--text-only"><div class="sd-guide-intro__body"><h2 id="新手上路" tabindex="-1"><a class="header-anchor" href="#新手上路" aria-hidden="true">#</a> 新手上路</h2><ol><li><strong>准备数据</strong>：训练图片 + 同名 <code>.txt</code> 标签；可用「工具与调试 → 数据集打标」。</li><li><strong>选择训练类型</strong>（侧栏「训练」）：<ul><li><strong>LoRA 训练</strong><ul><li><a href="/lora/sd3.html">Anima LoRA</a> — Anima DiT（推荐）</li><li><a href="/lora/anima-fast.html">Anima Fast</a> — 可选插件加速（进阶，页内安装）</li><li><a href="/lora/flux.html">Flux</a></li><li><a href="/lora/master.html">Stable Diffusion</a> — SD1.5 / SDXL LoRA</li></ul></li><li><strong>全量微调</strong><ul><li><a href="/lora/anima-finetune.html">Anima Finetune</a> — DiT 整模微调（高显存）</li><li><a href="/dreambooth/index.html">Stable Diffusion</a> — 默认 SDXL Finetune，可切换 SD1.5 Dreambooth</li></ul></li></ul></li><li><strong>填写参数并开训</strong>：中栏表单 → 右栏「开始训练」。</li><li><strong>查看进度</strong>：<a href="/train-monitor" target="_blank" rel="noopener noreferrer">训练监控</a>、<a href="/tensorboard.html">Tensorboard</a>。</li></ol></div></div></section><section class="sd-guide-pager__page" data-guide-page="1" id="guide-page-migrate" aria-label="从秋叶版迁移"><div class="sd-guide-migrate"><h2 id="从秋叶版迁移" tabindex="-1"><a class="header-anchor" href="#从秋叶版迁移" aria-hidden="true">#</a> 从秋叶版迁移</h2><p>若你使用过 <strong>Akegarasu/lora-scripts</strong>（秋叶一键包），本版主要变化：</p><ul><li><strong>品牌</strong>：项目名 <strong>lora-scripts-next</strong> / Next Trainer，侧栏按「训练 / 工具 / 帮助 / 其他」分组。</li><li><strong>导航</strong>：LoRA 与全量微调分栏；原「新手 / 专家」不再平铺（SD1.5 精简页：<a href="/lora/basic.html">/lora/basic.html</a>）。</li><li><strong>Anima</strong>：LoRA 与 Finetune 分入口（Qwen + T5 + DiT）。</li><li><strong>监控</strong>：独立 <a href="/train-monitor" target="_blank" rel="noopener noreferrer">训练监控页</a>、Loss 曲线、<code>/train-log</code> 日志流。</li><li>更多版本说明见 <a href="/other/changelog.html">更新日志</a>。</li></ul></div></section><section class="sd-guide-pager__page" data-guide-page="2" id="guide-page-fast" aria-label="Anima Fast"><section class="sd-guide-anima-fast"><h2 id="anima-fast-lora" tabindex="-1"><a class="header-anchor" href="#anima-fast-lora" aria-hidden="true">#</a> Anima LoRA · Fast 模式</h2><p>Anima 高速 LoRA 训练（进阶插件）。需单独安装 runtime，仅支持标准 LoRA。显存建议 16GB+，首次安装需下载数 GB 依赖。</p><p class="anima-fast-doc-links"><a href="https://github.com/wochenlong/lora-scripts-next/blob/main/docs/anima-fast.md" target="_blank" rel="noopener noreferrer">Fast 模式训练教程</a>（安装、数据路径、故障排除） · <a href="/lora/sd3.html">标准 Kohya 模式</a> · <a href="/lora/anima-fast.html"><strong>前往 Fast 训练页</strong></a></p><div class="anima-fast-dataset-guide anima-fast-dataset-guide__body"><p>Fast 训练<strong>实际读取 resized 目录</strong>里的 bucket 预处理图，不是直接读原图。</p> <ul> <li><strong>训练图片目录</strong>：原图 + caption（如 <code>data/xxx/子文件夹/</code>）</li> <li><strong>resized 目录</strong>：训练真正用到的 bucket PNG；<strong>留空</strong>时自动写入 <code>.cache/anima_fast/&lt;数据集路径&gt;/resized</code>（同一数据集可复用）</li> </ul> <p class="anima-fast-dataset-guide__highlight"><strong>可以填同一路径吗？</strong>可以。若该目录已是 bucket 预处理后的 PNG + caption，两处可填<strong>相同路径</strong>。</p> <p class="anima-fast-dataset-guide__note">输出 / cache 目录不存在时会自动创建。左侧「cache_latents」等保持关闭，除非已完成完整 preprocess。</p></div></section></section></div></div><nav class="sd-guide-pager__nav" aria-label="新手上路翻页"><button type="button" class="sd-guide-pager__btn" data-guide-prev disabled>上一页</button><span class="sd-guide-pager__count" data-guide-count>1 / 3</span><button type="button" class="sd-guide-pager__btn" data-guide-next>下一页</button></nav></div>`);function u(){return s(),a("div",null,[e("span",{"aria-hidden":"true",style:"display:none"},".",-1),h])}var x=n(_,[["render",u],["__file","guide.html.vue"]]);export{x as default};